//! A07/A08 differential reference: the accepted Rust decoders (lp1-node genesis_spec.rs and
//! header.rs, shared into pocold) give the verdict for every corpus input generated by
//! pocol-extension/tests/decoder_corpus.mjs. REFERENCE_WRITE=1 writes the verdict file; otherwise
//! the verdicts are checked against it, so the committed file is exactly the reference's output.
use std::path::PathBuf;
fn data(f:&str)->PathBuf{PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../pocol-extension/tests/data").join(f)}
fn unhex(s:&str)->Vec<u8>{(0..s.len()/2).map(|i|u8::from_str_radix(&s[2*i..2*i+2],16).unwrap()).collect()}
#[test] fn reference_verdicts_for_the_decoder_corpus(){
    let corpus:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(data("decoder-corpus.json")).unwrap()).unwrap();
    let mut out=serde_json::Map::new();
    for it in corpus["items"].as_array().unwrap(){
        let b=unhex(it["hex"].as_str().unwrap());
        let v=match it["kind"].as_str().unwrap(){
            "spec"=>match pocold::genesis_spec::decode(&b){Ok(_)=>"ok".to_string(),Err(e)=>format!("{}:{}",e.code,e.detail)},
            "header"=>match pocold::header::decode(&b){Ok(_)=>"ok".to_string(),Err(e)=>format!("1:{}",e.detail)},
            k=>panic!("kind {k}"),
        };
        out.insert(it["label"].as_str().unwrap().to_string(),serde_json::Value::String(v));
    }
    let got=serde_json::Value::Object(out);
    if std::env::var("REFERENCE_WRITE").is_ok(){std::fs::write(data("decoder-verdicts.json"),serde_json::to_string_pretty(&got).unwrap()+"\n").unwrap();return}
    let want:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(data("decoder-verdicts.json")).unwrap()).unwrap();
    assert_eq!(got,want,"the committed verdicts are not the reference decoders' output");
}
